namespace UniversityCourseCatalog.Models;

public class Department
{
    public int Id { get; set; }
    public string Name { get; set; } = "";
    public string Code { get; set; } = "";
    public string Description { get; set; } = "";
}

namespace UniversityCourseCatalog.Models;

public class Course
{
    public int Id { get; set; }
    public string Title { get; set; } = "";
    public string Code { get; set; } = "";
    public string Description { get; set; } = "";
    public int Credits { get; set; }
    public string Schedule { get; set; } = "";
    public string Instructor { get; set; } = "";
    public string InstructorBio { get; set; } = "";
    public int DepartmentId { get; set; }
    public string DepartmentName { get; set; } = "";
    public bool IsFeatured { get; set; }
}

using System.ComponentModel.DataAnnotations;

namespace UniversityCourseCatalog.Models;

public class EnrollmentRequest
{
    [Required(ErrorMessage = "Full name is required.")]
    [StringLength(100, ErrorMessage = "Name cannot exceed 100 characters.")]
    public string FullName { get; set; } = "";

    [Required(ErrorMessage = "Student ID is required.")]
    [RegularExpression(@"^[A-Za-z0-9]{6,12}$", ErrorMessage = "Student ID must be 6–12 alphanumeric characters.")]
    public string StudentId { get; set; } = "";

    [Required(ErrorMessage = "Please select a course.")]
    [Range(1, int.MaxValue, ErrorMessage = "Please select a course.")]
    public int CourseId { get; set; }
}

using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public class CatalogService
{
    private readonly List<Department> _departments;
    private readonly List<Course> _courses;

    public CatalogService()
    {
        _departments = new List<Department>
        {
            new() { Id = 1, Name = "Computer Science", Code = "CS", Description = "Study of computation, algorithms, and information systems." },
            new() { Id = 2, Name = "Mathematics", Code = "MATH", Description = "Pure and applied mathematics, statistics, and data analysis." },
            new() { Id = 3, Name = "Physics", Code = "PHYS", Description = "Fundamental laws of nature, mechanics, and modern physics." },
            new() { Id = 4, Name = "English", Code = "ENG", Description = "Literature, writing, and critical communication skills." },
            new() { Id = 5, Name = "History", Code = "HIST", Description = "World history, civilizations, and historiography." },
        };

        _courses = new List<Course>
        {
            // Computer Science
            new() { Id = 1, Title = "Introduction to Programming", Code = "CS 101", Description = "Fundamentals of programming using Python. Covers variables, control flow, functions, and basic data structures. No prior experience required.", Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", Instructor = "Dr. Alice Chen", InstructorBio = "Dr. Chen holds a Ph.D. in Software Engineering from MIT and has 15 years of teaching experience. Her research focuses on programming education and developer tools.", DepartmentId = 1, DepartmentName = "Computer Science", IsFeatured = true },
            new() { Id = 2, Title = "Data Structures & Algorithms", Code = "CS 201", Description = "In-depth study of arrays, linked lists, trees, graphs, sorting, and searching algorithms. Emphasis on algorithmic complexity and problem-solving.", Credits = 4, Schedule = "Tue/Thu 10:30 AM–12:00 PM", Instructor = "Dr. Bob Martinez", InstructorBio = "Dr. Martinez is an ACM Distinguished Educator with publications in algorithm design. He previously worked at Google Research.", DepartmentId = 1, DepartmentName = "Computer Science", IsFeatured = true },
            new() { Id = 3, Title = "Database Systems", Code = "CS 340", Description = "Relational database design, SQL, normalization, indexing, and transaction management. Includes a hands-on project building a full database application.", Credits = 3, Schedule = "Mon/Wed 2:00–3:20 PM", Instructor = "Prof. Carol Singh", InstructorBio = "Prof. Singh spent a decade as a database architect at Oracle before joining academia. She specializes in distributed data systems.", DepartmentId = 1, DepartmentName = "Computer Science" },
            new() { Id = 4, Title = "Operating Systems", Code = "CS 350", Description = "Process management, memory management, file systems, and concurrency. Students implement core OS components in C.", Credits = 4, Schedule = "Tue/Thu 1:00–2:30 PM", Instructor = "Dr. David Park", InstructorBio = "Dr. Park is a systems researcher whose work on kernel optimization has been adopted by several Linux distributions.", DepartmentId = 1, DepartmentName = "Computer Science" },

            // Mathematics
            new() { Id = 5, Title = "Calculus I", Code = "MATH 151", Description = "Limits, derivatives, and integrals of single-variable functions. Applications to physics, engineering, and economics.", Credits = 4, Schedule = "Mon/Wed/Fri 10:00–10:50 AM", Instructor = "Dr. Elena Rossi", InstructorBio = "Dr. Rossi is an award-winning educator and author of two calculus textbooks used at universities worldwide.", DepartmentId = 2, DepartmentName = "Mathematics", IsFeatured = true },
            new() { Id = 6, Title = "Linear Algebra", Code = "MATH 220", Description = "Vector spaces, matrices, determinants, eigenvalues, and linear transformations. Foundation for advanced math and machine learning.", Credits = 3, Schedule = "Tue/Thu 9:00–10:20 AM", Instructor = "Dr. Frank Liu", InstructorBio = "Dr. Liu's research in numerical linear algebra has applications in computer graphics and scientific computing.", DepartmentId = 2, DepartmentName = "Mathematics" },
            new() { Id = 7, Title = "Probability & Statistics", Code = "MATH 310", Description = "Probability theory, random variables, distributions, hypothesis testing, and regression analysis.", Credits = 3, Schedule = "Mon/Wed 11:00 AM–12:20 PM", Instructor = "Dr. Grace Kim", InstructorBio = "Dr. Kim is a biostatistician who collaborates with the medical school on clinical trial design.", DepartmentId = 2, DepartmentName = "Mathematics" },

            // Physics
            new() { Id = 8, Title = "General Physics I", Code = "PHYS 101", Description = "Classical mechanics: kinematics, Newton's laws, energy, momentum, rotational motion, and oscillations. Includes weekly lab.", Credits = 4, Schedule = "Mon/Wed/Fri 11:00–11:50 AM + Lab Thu 2:00–4:50 PM", Instructor = "Dr. Henry Wallace", InstructorBio = "Dr. Wallace is an experimental physicist with 20 years of experience teaching introductory physics courses.", DepartmentId = 3, DepartmentName = "Physics", IsFeatured = true },
            new() { Id = 9, Title = "Quantum Mechanics", Code = "PHYS 401", Description = "Wave-particle duality, Schrödinger equation, quantum states, measurement theory, and applications to atomic physics.", Credits = 3, Schedule = "Tue/Thu 3:00–4:20 PM", Instructor = "Dr. Irene Foster", InstructorBio = "Dr. Foster's quantum optics research has been published in Nature Physics. She holds two patents in quantum sensing.", DepartmentId = 3, DepartmentName = "Physics" },

            // English
            new() { Id = 10, Title = "Academic Writing", Code = "ENG 101", Description = "Develop clear, persuasive writing skills for academic and professional contexts. Covers essay structure, argumentation, and research methods.", Credits = 3, Schedule = "Mon/Wed/Fri 1:00–1:50 PM", Instructor = "Prof. Julia Grant", InstructorBio = "Prof. Grant is a published author and former editor at The Atlantic. She has taught writing at three universities.", DepartmentId = 4, DepartmentName = "English" },
            new() { Id = 11, Title = "American Literature", Code = "ENG 250", Description = "Survey of American literary works from the colonial period to the present, including novels, poetry, and essays.", Credits = 3, Schedule = "Tue/Thu 11:00 AM–12:20 PM", Instructor = "Dr. Kevin Brooks", InstructorBio = "Dr. Brooks specializes in 20th-century American fiction and has written extensively on the works of Toni Morrison.", DepartmentId = 4, DepartmentName = "English" },

            // History
            new() { Id = 12, Title = "World History to 1500", Code = "HIST 101", Description = "Major civilizations, cultural exchanges, and turning points in human history from prehistory through the late medieval period.", Credits = 3, Schedule = "Mon/Wed 3:30–4:50 PM", Instructor = "Dr. Laura Nakamura", InstructorBio = "Dr. Nakamura is a historian of ancient trade networks. Her book on Silk Road commerce won the AHA Prize.", DepartmentId = 5, DepartmentName = "History" },
            new() { Id = 13, Title = "Modern European History", Code = "HIST 301", Description = "Europe from the Enlightenment through the 21st century: revolutions, world wars, decolonization, and European integration.", Credits = 3, Schedule = "Tue/Thu 2:00–3:20 PM", Instructor = "Dr. Marco Petrov", InstructorBio = "Dr. Petrov is a specialist in Cold War diplomacy and has consulted for several documentary film projects.", DepartmentId = 5, DepartmentName = "History" },
        };
    }

    public List<Department> GetDepartments() => _departments;

    public Department? GetDepartment(int id) => _departments.FirstOrDefault(d => d.Id == id);

    public List<Course> GetAllCourses() => _courses;

    public List<Course> GetFeaturedCourses() => _courses.Where(c => c.IsFeatured).ToList();

    public Course? GetCourse(int id) => _courses.FirstOrDefault(c => c.Id == id);

    public List<Course> SearchCourses(string? search, int? departmentId)
    {
        var query = _courses.AsEnumerable();

        if (departmentId.HasValue && departmentId.Value > 0)
            query = query.Where(c => c.DepartmentId == departmentId.Value);

        if (!string.IsNullOrWhiteSpace(search))
        {
            var term = search.Trim();
            query = query.Where(c =>
                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Code.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Instructor.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Description.Contains(term, StringComparison.OrdinalIgnoreCase));
        }

        return query.ToList();
    }
}

