@using UniversityCourseCatalog.Models
@using UniversityCourseCatalog.Services
@inject CatalogService Catalog

<PageTitle>Enrollment Request</PageTitle>

<h1 class="mb-4">Enrollment Request</h1>

@if (submitted)
{
    <div class="alert alert-success">
        <h4 class="alert-heading">Request Submitted!</h4>
        <p>Thank you, <strong>@Model.FullName</strong>. Your enrollment request for
            <strong>@(selectedCourseTitle)</strong> has been received and will be reviewed by the registrar.</p>
        <hr />
        <a href="/courses" class="btn btn-outline-success">Browse More Courses</a>
    </div>
}
else
{
    <div class="row">
        <div class="col-lg-7">
            <EditForm method="post" Model="Model" OnValidSubmit="HandleSubmit" FormName="enrollment" Enhance>
                <DataAnnotationsValidator />
                <AntiforgeryToken />

                <div class="mb-3">
                    <label for="fullName" class="form-label">Full Name</label>
                    <InputText id="fullName" @bind-Value="Model.FullName" class="form-control" />
                    <ValidationMessage For="() => Model.FullName" class="text-danger" />
                </div>

                <div class="mb-3">
                    <label for="studentId" class="form-label">Student ID</label>
                    <InputText id="studentId" @bind-Value="Model.StudentId" class="form-control" placeholder="e.g. ABC12345" />
                    <ValidationMessage For="() => Model.StudentId" class="text-danger" />
                </div>

                <div class="mb-3">
                    <label for="courseId" class="form-label">Course</label>
                    <InputSelect id="courseId" @bind-Value="Model.CourseId" class="form-select">
                        <option value="0">— Select a course —</option>
                        @foreach (var course in allCourses)
                        {
                            <option value="@course.Id">@course.Code — @course.Title</option>
                        }
                    </InputSelect>
                    <ValidationMessage For="() => Model.CourseId" class="text-danger" />
                </div>

                <button type="submit" class="btn btn-primary">Submit Request</button>
            </EditForm>
        </div>

        <div class="col-lg-5">
            <div class="card bg-light mt-4 mt-lg-0">
                <div class="card-body">
                    <h5 class="card-title">How It Works</h5>
                    <ol class="mb-0">
                        <li>Fill in your name and student ID.</li>
                        <li>Select the course you'd like to enroll in.</li>
                        <li>Submit your request — the registrar will review it and notify you via email.</li>
                    </ol>
                </div>
            </div>
        </div>
    </div>
}

@code {
    [SupplyParameterFromForm] private EnrollmentRequest Model { get; set; } = new();
    [SupplyParameterFromQuery] public int? CourseId { get; set; }

    private List<Course> allCourses = new();
    private bool submitted;
    private string selectedCourseTitle = "";

    protected override void OnInitialized()
    {
        allCourses = Catalog.GetAllCourses();

        // Pre-select course if arriving from a course detail page
        if (CourseId.HasValue && Model.CourseId == 0)
        {
            Model.CourseId = CourseId.Value;
        }
    }

    private void HandleSubmit()
    {
        var course = Catalog.GetCourse(Model.CourseId);
        selectedCourseTitle = course is not null ? $"{course.Code} — {course.Title}" : "Unknown Course";
        submitted = true;
    }
}
