toolArgs.new_str:
@page "/"
@using UniversityCourseCatalog.Models
@using UniversityCourseCatalog.Services
@inject CatalogService Catalog

<PageTitle>University Course Catalog</PageTitle>

<div class="hero-banner mb-5 p-5 rounded-3 text-center bg-primary text-white">
    <h1 class="display-4 fw-bold">University Course Catalog</h1>
    <p class="lead mb-4">Explore departments, discover courses, and start your enrollment today.</p>
    <a href="/courses" class="btn btn-light btn-lg">Browse All Courses</a>
</div>

<section class="mb-5">
    <h2 class="mb-3">Featured Courses</h2>
    <div class="row g-4">
        @foreach (var course in featuredCourses)
        {
            <div class="col-md-6 col-lg-3">
                <div class="card h-100 shadow-sm">
                    <div class="card-body d-flex flex-column">
                        <span class="badge bg-secondary mb-2 align-self-start">@course.Code</span>
                        <h5 class="card-title">@course.Title</h5>
                        <p class="card-text text-muted small flex-grow-1">@course.DepartmentName &middot; @course.Credits credits</p>
                        <a href="/courses/@course.Id" class="btn btn-outline-primary btn-sm mt-2">View Details</a>
                    </div>
                </div>
            </div>
        }
    </div>
</section>

<section class="mb-5">
    <h2 class="mb-3">Departments</h2>
    <div class="row g-3">
        @foreach (var dept in departments)
        {
            <div class="col-md-6 col-lg-4">
                <div class="card h-100 border-start border-primary border-4">
                    <div class="card-body">
                        <h5 class="card-title">@dept.Name</h5>
                        <p class="card-text text-muted small">@dept.Description</p>
                        <a href="/courses?departmentId=@dept.Id" class="stretched-link text-decoration-none">
                            Browse @dept.Code courses &rarr;
                        </a>
                    </div>
                </div>
            </div>
        }
    </div>
</section>

@code {
    private List<Course> featuredCourses = new();
    private List<Department> departments = new();

    protected override void OnInitialized()
    {
        featuredCourses = Catalog.GetFeaturedCourses();
        departments = Catalog.GetDepartments();
    }
}

